<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ArtFlow Management System | Business Platform</title>
<style>
:root{--blue:#2563eb;--navy:#071a35;--ink:#12213a;--muted:#64748b;--line:#e2e8f0;--bg:#f8fafc;--red:#dc2626}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:var(--bg);font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{text-decoration:none;color:inherit}.wrap{width:min(1160px,calc(100% - 32px));margin:auto}.hero{min-height:650px;color:#fff;background:linear-gradient(110deg,rgba(4,18,40,.98),rgba(8,44,91,.87)),url('https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1800&q=80') center/cover}.nav{height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid rgba(255,255,255,.14)}.brand{display:flex;align-items:center;gap:10px;font-weight:900;letter-spacing:.03em}.brand-mark{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#2563eb;font-size:12px}.brand small{display:block;color:#93c5fd;font-size:9px;letter-spacing:.18em}.nav-links{display:flex;gap:18px;color:#cbd5e1;font-size:12px;font-weight:700}.nav-links a:hover{color:#fff}.nav-login{color:#fff;border:1px solid rgba(255,255,255,.35);border-radius:8px;padding:9px 13px;font-size:12px;font-weight:800}.hero-content{padding:115px 0 78px;max-width:700px}.eyebrow,.accent{color:#93c5fd;font-size:11px;font-weight:900;letter-spacing:.16em}.hero h1{margin:16px 0 17px;font-size:clamp(40px,6vw,72px);line-height:1.02;letter-spacing:-.065em}.hero p{max-width:600px;color:#cbd5e1;font-size:18px;line-height:1.65}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:28px}.btn{display:inline-flex;align-items:center;justify-content:center;border:1px solid transparent;border-radius:8px;padding:11px 16px;font-size:12px;font-weight:850;cursor:pointer}.primary{background:var(--blue);color:#fff}.outline{border-color:#94a3b8;background:transparent;color:#fff}.offer{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-top:48px;padding:14px 17px;border:1px solid rgba(147,197,253,.35);border-radius:11px;background:rgba(15,23,42,.65);font-size:12px}.offer strong{color:#fca5a5;margin-right:8px;font-size:10px}.offer a{color:#fff;background:var(--red);border-radius:7px;padding:8px 12px;font-weight:800;white-space:nowrap}section{padding:78px 0}.section-title{text-align:center;margin-bottom:35px}.section-title h2{margin:0;color:var(--ink);font-size:32px;letter-spacing:-.05em}.section-title p{max-width:650px;margin:10px auto 0;color:var(--muted);font-size:13px;line-height:1.65}.offline,.demo-grid{display:grid;grid-template-columns:1fr 1fr;gap:45px;align-items:center}.offline h2,.demo h2{margin:10px 0;font-size:38px;letter-spacing:-.055em}.offline p,.demo-copy p{color:var(--muted);font-size:14px;line-height:1.75}.offline-image{min-height:330px;border-radius:18px;background:linear-gradient(135deg,rgba(15,23,42,.1),rgba(37,99,235,.18)),url('https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1000&q=80') center/cover;box-shadow:0 22px 45px rgba(15,23,42,.16)}.demo{background:#eff6ff;border-top:1px solid #dbeafe;border-bottom:1px solid #dbeafe}.bullets{display:grid;gap:14px;margin:24px 0;padding:0;list-style:none}.bullets li{display:flex;gap:10px;color:#475569;font-size:13px;line-height:1.55}.check{color:#10b981;font-weight:900}.form-card{padding:25px;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 12px 30px rgba(15,23,42,.08)}.form-card h3{margin:0;font-size:20px}.form-card p{margin:7px 0 18px;color:var(--muted);font-size:12px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:5px}.field.full{grid-column:1/-1}.field label{color:#475569;font-size:11px;font-weight:800}.field input,.field select,.field textarea{width:100%;border:1px solid var(--line);border-radius:8px;padding:10px;font:inherit;font-size:12px;outline:none}.field textarea{min-height:72px}.success{margin-bottom:14px;padding:10px;border-radius:8px;background:#ecfdf5;color:#047857;font-size:12px;font-weight:700}.features,.products{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.feature,.product,.team-card,.contact-card{border:1px solid var(--line);border-radius:13px;background:#fff;box-shadow:0 5px 15px rgba(15,23,42,.04)}.feature{padding:19px}.feature h3{display:inline-block;margin:0;font-size:14px}.feature h3:after{content:'';display:block;width:30px;height:2px;margin-top:6px;background:var(--red)}.feature p,.product p{margin:10px 0 0;color:var(--muted);font-size:11px;line-height:1.6}.products-section{background:#eff6ff;border-top:1px solid var(--line)}.product{padding:18px;min-height:180px}.product.active{border-color:var(--blue);box-shadow:0 0 0 3px #bfdbfe}.product-icon{display:grid;place-items:center;width:40px;height:40px;margin-bottom:13px;border-radius:10px;background:#dbeafe;color:var(--blue);font-size:19px;font-weight:900}.product h3{margin:0;font-size:14px}.product-actions{display:flex;gap:6px;margin-top:18px}.product-actions .btn{flex:1;padding:8px 5px;font-size:10px}.dark{background:#0f172a;color:#fff}.team-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.team-card{padding:18px;display:flex;gap:14px}.team-card img{width:84px;height:105px;object-fit:cover;border-radius:10px}.team-card h3{margin:0;font-size:14px}.role{display:inline-block;margin-top:5px;padding:4px 7px;border-radius:999px;background:#eff6ff;color:#1d4ed8;font-size:9px;font-weight:800}.team-card p{margin:9px 0 0;color:var(--muted);font-size:11px;line-height:1.55}.phone{display:block;margin-top:9px;font-size:11px;font-weight:800}.footer{padding:54px 0 28px;background:#fff;border-top:1px solid var(--line);text-align:center}.footer h2{margin:7px 0 0;font-size:30px;letter-spacing:.03em}.redline{width:60px;height:2px;margin:12px auto;background:var(--red)}.contact-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:34px auto;max-width:980px;text-align:left}.contact-card{display:flex;gap:10px;align-items:center;padding:15px;background:#f8fafc}.contact-icon{display:grid;place-items:center;width:35px;height:35px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--blue);font-weight:900}.contact-card small{display:block;color:#94a3b8;font-size:9px;font-weight:900}.contact-card strong,.contact-card span{display:block;margin-top:3px;color:#334155;font-size:11px}.footer-links{display:flex;flex-wrap:wrap;justify-content:center;gap:20px;padding-top:25px;border-top:1px solid var(--line);font-size:11px;font-weight:800;color:#475569}.socials{display:flex;justify-content:center;gap:8px;margin-top:20px}.social{display:grid;place-items:center;width:30px;height:30px;border:1px solid var(--line);border-radius:50%;background:#f1f5f9;color:#475569;font-size:10px;font-weight:900}.top-button{position:fixed;right:20px;bottom:20px;width:40px;height:40px;border:0;border-radius:8px;background:var(--blue);color:#fff;cursor:pointer;font-size:18px}@media(max-width:900px){.nav-links{display:none}.features,.products{grid-template-columns:repeat(2,1fr)}.contact-grid{grid-template-columns:repeat(2,1fr)}.cta-row{flex-direction:column}.demo-grid{grid-template-columns:1fr}.offering-grid{grid-template-columns:repeat(2,1fr)}.team-grid{grid-template-columns:repeat(2,1fr)}.partner-grid{grid-template-columns:repeat(3,1fr)}.top-button{right:16px;bottom:16px}}@media(max-width:650px){.hero-content{padding:75px 0 60px}.offer{align-items:flex-start;flex-direction:column}.offline,.demo-grid{grid-template-columns:1fr;gap:25px}.offline h2,.demo h2{font-size:30px}.features,.products,.team-grid,.contact-grid{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.field.full{grid-column:auto}.footer-links{gap:12px}}
</style>
<style>
.coming-soon{display:inline-block;margin-top:11px;padding:4px 8px;border-radius:999px;background:#f1f5f9;color:#64748b;font-size:9px;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.btn.disabled{background:#f1f5f9;color:#94a3b8;border-color:#e2e8f0;cursor:not-allowed;pointer-events:none}
</style>
<style>
.apos-nav{position:relative}.apos-trigger{color:#cbd5e1;font:inherit;font-size:12px;font-weight:700;border:0;background:transparent;cursor:pointer;padding:0}.apos-menu{display:none;position:absolute;right:-20px;top:24px;width:310px;padding:9px;border:1px solid #334155;border-radius:14px;background:rgba(15,23,42,.97);box-shadow:0 20px 40px rgba(15,23,42,.28);z-index:10}.apos-nav:hover .apos-menu,.apos-nav:focus-within .apos-menu{display:grid;gap:3px}.apos-item{display:grid;grid-template-columns:30px 1fr;gap:9px;padding:10px;border-radius:10px;color:#e2e8f0}.apos-item:hover{background:#1e293b;color:#5eead4}.apos-item-icon{display:grid;place-items:center;width:28px;height:28px;border-radius:8px;background:#1e3a8a;color:#bfdbfe;font-size:13px}.apos-item strong{display:block;font-size:11px}.apos-item small{display:block;margin-top:2px;color:#94a3b8;font-size:10px;line-height:1.35}@media(max-width:900px){.apos-menu{position:fixed;right:16px;top:60px}.apos-nav:hover .apos-menu{display:none}.apos-nav:focus-within .apos-menu{display:grid}}
</style>
<style>
.nav-links>a,.apos-trigger{position:relative}
.nav-links>a::after,.apos-trigger::after{position:absolute;right:50%;bottom:-6px;left:50%;height:2px;border-radius:2px;background:#5eead4;content:"";transform:translateX(-50%);transition:width .28s ease-out}
@media(hover:hover){.nav-links>a:hover::after,.apos-trigger:hover::after{width:84%}}
.nav-links>a:focus-visible::after,.apos-trigger:focus-visible::after{width:84%}
@media(prefers-reduced-motion:reduce){.nav-links>a::after,.apos-trigger::after{transition:none}}
</style>
<style>
	:root { --blue: #0f766e; --navy: #12343b; --ink: #17313a; --red: #d97706; }
	.hero { background: linear-gradient(110deg, rgba(9, 30, 35, .98), rgba(15, 118, 110, .86)), url('https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1800&q=80') center/cover; }
	.brand-mark, .primary, .top-button { background: #0f766e; }
	.nav-login { border-color: rgba(153, 246, 228, .45); }
	.eyebrow, .accent { color: #5eead4; }
	.offer a { background: #d97706; }
	.offline-image { background: linear-gradient(135deg, rgba(15, 23, 42, .1), rgba(13, 148, 136, .2)), url('https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1000&q=80') center/cover; }
	.demo { background: #ecfeff; border-color: #ccfbf1; }
	.product-icon, .role { background: #ccfbf1; color: #0f766e; }
	.product.active { border-color: #0f766e; box-shadow: 0 0 0 3px #99f6e4; }
	.feature h3:after, .redline { background: #d97706; }
	.contact-icon { color: #0f766e; }
	.social:hover { background: #0f766e; }
</style>
<style>
.why-section{background:#f8fafc;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.why-hero{text-align:center;max-width:760px;margin:0 auto 30px}.why-hero h2{margin:10px 0;font-size:32px;letter-spacing:-.05em}.why-hero p{color:var(--muted);font-size:13px;line-height:1.65}.why-accent{width:58px;height:3px;margin:12px auto;background:var(--blue)}.reason-filters{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin-bottom:20px}.reason-filter{border:1px solid var(--line);border-radius:999px;padding:9px 13px;background:#fff;color:#475569;font-size:11px;font-weight:800;cursor:pointer}.reason-filter.active,.reason-filter:hover{border-color:var(--blue);background:var(--blue);color:#fff}.reason-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.reason-card{display:flex;gap:15px;padding:20px;border:1px solid var(--line);border-radius:14px;background:#fff;box-shadow:0 5px 15px rgba(15,23,42,.04)}.reason-icon{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;border:1px solid #cde6e0;border-radius:50%;background:#eaf5f3;color:#0f766e}.reason-icon-svg{display:block;width:21px;height:21px}.reason-card h3{margin:0;font-size:15px}.reason-card p{margin:7px 0 0;color:var(--muted);font-size:12px;line-height:1.6}.why-cta{text-align:center;margin:30px auto 0;padding:38px 24px;border:1px solid #dbeafe;border-radius:18px;background:#eff6ff;color:#12213a}.why-cta h3{margin:0;color:#12213a;font-size:21px}.why-cta p{margin:8px auto 14px;color:#64748b;font-size:12px;line-height:1.6}@media(max-width:650px){.reason-grid{grid-template-columns:1fr}.why-hero h2{font-size:27px}.why-cta{padding:30px 18px}}
</style>
