<style>
.team-section{padding:78px 0 84px;background:linear-gradient(180deg,#f8fafc 0%,#fff 100%);border-top:1px solid #edf2f7;border-bottom:1px solid #edf2f7}
.team-intro{text-align:center;max-width:760px;margin:0 auto 34px}
.team-kicker{display:inline-flex;align-items:center;gap:8px;color:#0f766e;font-size:10px;font-weight:900;letter-spacing:.18em;text-transform:uppercase}
.team-kicker::before,.team-kicker::after{content:"";width:22px;height:1px;background:#99cfc8}
.team-intro h2{margin:12px 0 10px;color:#102a43;font-size:clamp(28px,4vw,40px);line-height:1.15;letter-spacing:-.045em}
.team-subtitle{margin:0;color:#334e68;font-size:15px;font-weight:650;line-height:1.65}
.team-intro-copy{max-width:680px;margin:10px auto 0;color:#64748b;font-size:13px;line-height:1.75}
.team-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:stretch;gap:24px;max-width:1000px;margin:0 auto}
.team-section .team-card{position:relative;display:flex;flex-direction:column;min-width:0;overflow:visible;border:1px solid #e2e8f0;border-radius:22px;background:#fff;box-shadow:0 12px 32px rgba(16,42,67,.07);transition:box-shadow .24s ease,border-color .24s ease}
.team-section .team-card:hover,.team-section .team-card:focus-within{transform:none;border-color:#b8d8d5;box-shadow:0 20px 42px rgba(16,42,67,.12)}
.team-photo{position:relative;z-index:0;display:grid;place-items:center;height:260px;flex:0 0 260px;overflow:visible;background:linear-gradient(135deg,#eef8f7,#f4f7fb);border-bottom:1px solid #e8eef2}
.team-photo.raheel{background:linear-gradient(135deg,#e8f5f3,#f5f8fb 70%)}
.team-photo.shahrukh{background:linear-gradient(135deg,#eef3f8,#f7f8fa 70%)}
.team-photo img{position:absolute;top:50%;left:50%;z-index:3;display:block;width:210px;height:210px;max-width:calc(100% - 24px);border:3px solid rgba(255,255,255,.92);border-radius:50%;background:#fff;box-shadow:0 6px 16px rgba(16,42,67,.14);object-fit:cover;object-position:center;transform:translate(-50%,-50%);transition:transform .4s ease-out,box-shadow .4s ease-out,border-color .4s ease-out}
.team-photo.raheel img{object-position:center 15%}
.team-photo.shahrukh img{object-position:center 50%}
.team-photo::after{position:absolute;inset:0;z-index:1;content:"";background:linear-gradient(180deg,rgba(9,30,35,0) 44%,rgba(9,30,35,.48) 100%);opacity:0;pointer-events:none;transition:opacity .35s ease-out}
.team-photo-popup{position:absolute;right:14px;bottom:14px;left:14px;z-index:2;padding:11px 14px;border:1px solid rgba(255,255,255,.7);border-radius:13px;background:rgba(255,255,255,.84);box-shadow:0 8px 22px rgba(7,26,53,.14);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);color:#102a43;font-size:11px;font-weight:850;letter-spacing:.025em;line-height:1.45;opacity:0;transform:translateY(25px);visibility:hidden;transition:opacity .35s ease-out,transform .35s ease-out,visibility .35s ease-out}
.team-section .team-card:hover .team-photo::after,.team-section .team-card:focus-within .team-photo::after{opacity:1}
.team-section .team-card:hover .team-photo-popup,.team-section .team-card:focus-within .team-photo-popup{opacity:1;transform:translateY(0);visibility:visible}
.team-photo:hover,.team-photo:focus-within{z-index:5}
@media(hover:hover) and (prefers-reduced-motion:no-preference){.team-photo img:hover,.team-photo:focus-visible img{border-color:rgba(255,255,255,.96);box-shadow:0 9px 20px rgba(16,42,67,.2);transform:translate(-50%,calc(-50% - 3px)) scale(1.12)}}
.team-card-body{display:flex;flex:1;flex-direction:column;padding:22px 24px 25px}
.team-card h3{margin:0;color:#102a43;font-size:clamp(22px,2.5vw,27px);line-height:1.2;letter-spacing:-.04em}
.team-role{align-self:flex-start;display:inline-flex;margin-top:10px;padding:6px 10px;border:1px solid #cce8e4;border-radius:999px;background:#f0fdfa;color:#0f766e;font-size:9px;font-weight:900;letter-spacing:.11em;text-transform:uppercase;transition:background .2s ease,border-color .2s ease}
.team-section .team-card:hover .team-role{border-color:#a8d5cf;background:#e8f7f4}
.team-education{margin:18px 0 0;color:#334e68;font-size:12px;font-weight:750;line-height:1.6}
.team-detail-label{display:block;margin-bottom:4px;color:#8293a5;font-size:9px;font-weight:900;letter-spacing:.14em;text-transform:uppercase}
.team-bio{margin:12px 0 0;color:#526579;font-size:12px;line-height:1.75}
@media(max-width:700px){.team-section{padding:58px 0 64px}.team-intro{margin-bottom:26px}.team-grid{grid-template-columns:1fr;max-width:520px;gap:18px}}
@media(max-width:900px) and (min-width:701px) and (hover:hover) and (prefers-reduced-motion:no-preference){.team-photo img:hover,.team-photo:focus-visible img{transform:translate(-50%,calc(-50% - 2px)) scale(1.08)}}
@media(max-width:700px) and (hover:hover) and (prefers-reduced-motion:no-preference){.team-photo img:hover,.team-photo:focus-visible img{transform:translate(-50%,calc(-50% - 1px)) scale(1.04)}}
@media(max-width:420px){.team-photo{height:230px;flex-basis:230px}.team-card-body{padding:20px}}
@media(hover:none){.team-photo::after{opacity:.55}.team-photo-popup{opacity:1;transform:none;visibility:visible}}
@media(prefers-reduced-motion:reduce){.team-section .team-card,.team-role,.team-photo img,.team-photo::after,.team-photo-popup{transition:none}.team-section .team-card:hover,.team-section .team-card:focus-within{transform:none}.team-photo img:hover,.team-photo:focus-within img{transform:translate(-50%,-50%);box-shadow:0 6px 16px rgba(16,42,67,.14);border-color:rgba(255,255,255,.92)}.team-section .team-card:hover .team-photo-popup,.team-section .team-card:focus-within .team-photo-popup{transform:none}}
</style>
<style>
.social{position:relative;transition:background-color .2s ease,border-color .2s ease,color .2s ease,transform .2s ease}
.social svg{display:none;width:16px;height:16px;fill:currentColor}
.social:hover,.social:focus-visible{color:#fff;transform:translateY(-2px)}
.social:hover .social-label,.social:focus-visible .social-label{display:none}
.social:hover svg,.social:focus-visible svg{display:block}
.social.facebook:hover,.social.facebook:focus-visible{background:#1877f2;border-color:#1877f2}
.social.instagram:hover,.social.instagram:focus-visible{background:#c13584;border-color:#c13584}
.social.linkedin:hover,.social.linkedin:focus-visible{background:#0a66c2;border-color:#0a66c2}
.social.whatsapp:hover,.social.whatsapp:focus-visible{background:#25d366;border-color:#25d366}
.product-actions .btn{min-height:38px;padding:9px 12px;border:1px solid transparent;border-radius:9px;font-size:11px;font-weight:850;box-shadow:0 3px 8px rgba(15,23,42,.12);transition:background-color .18s ease,border-color .18s ease,box-shadow .18s ease,transform .18s ease}
.product-actions .btn.dark{border-color:#0f172a;background:#0f172a;color:#fff}
.product-actions .btn:not(.dark){border-color:#0f766e;background:#0f766e;color:#fff}
.product-actions .btn:hover{transform:translateY(-1px);box-shadow:0 6px 14px rgba(15,23,42,.18)}
.product-actions .btn.dark:hover{border-color:#1e293b;background:#1e293b}
.product-actions .btn:not(.dark):hover{border-color:#0b625d;background:#0b625d}
.product-actions .btn:focus-visible{outline:3px solid rgba(20,184,166,.38);outline-offset:2px}
@media(prefers-reduced-motion:reduce){.social{transition:none}.social:hover,.social:focus-visible{transform:none}}
</style>
